ALTER TABLE "topics" ADD COLUMN "block_reason" text;--> statement-breakpoint
ALTER TABLE "topics" ADD CONSTRAINT "topics_block_state_check" CHECK (("topics"."blocked_at" is null and "topics"."block_reason" is null) or ("topics"."blocked_at" is not null and "topics"."status" = 'archived' and "topics"."block_reason" is not null and length("topics"."block_reason") between 1 and 500));